def write_document_indices(data_path: Path, *, dtype, eos_token_id: int) -> Path:
    token_ids = np.memmap(data_path, mode='r', dtype=dtype)
    eos_token_locations = (token_ids == eos_token_id).nonzero()[0]
    metadata_path = data_path.with_suffix('.csv.gz')
    with gzip.open(metadata_path, mode='wt') as f:
        start_idx = 0
        for eos_token_location in eos_token_locations:
            end_idx = eos_token_location + 1
            f.write(f'{start_idx},{end_idx}\n')
            start_idx = end_idx
    return metadata_path

def iter_document_indices(data_path: PathOrStr, *, local_cache: Optional[PathOrStr]=None, use_array_if_local: Optional[bool]=None, eos_token_id: Optional[int]=None, dtype=None) -> Generator[Tuple[int, int], None, None]:
    if use_array_if_local is None:
        if eos_token_id is not None and dtype is not None and (not is_url(data_path)):
            use_array_if_local = True
    if use_array_if_local and (not is_url(data_path)):
        if eos_token_id is None or dtype is None:
            raise ValueError("'eos_token_id' and 'dtype' are required to use the local array for finding document indices")
        mmap = np.memmap(data_path, mode='r', dtype=dtype)
        doc_boundaries = (mmap == eos_token_id).nonzero()[0]
        start_idx = 0
        end_idx = 0
        for idx in doc_boundaries:
            end_idx = idx + 1
            yield (start_idx, end_idx)
            start_idx = end_idx
    else:
        metadata_filename = os.path.basename(data_path).replace('.npy', '.csv.gz')
        try:
            metadata_path = resource_path(os.path.dirname(data_path), metadata_filename, local_cache=local_cache)
        except FileNotFoundError as e:
            raise RuntimeError(f"Source metadata file '{metadata_filename}' is required to calculate document indices for '{data_path}'. If the source data file is local (on-disk) and 'eos_token_id' and 'dtype' are provided, then the document indices can be inferred from the source file.") from e
        total_tokens: Optional[int] = None
        if dtype is not None:
            total_tokens = get_file_size(data_path) // dtype(0).itemsize
        with gzip.open(metadata_path, 'rt') as f:
            for line in f:
                start_index_str, end_index_str, *_ = line.split(',')
                start_index, end_index = (int(start_index_str), int(end_index_str))
                if total_tokens is not None:
                    if start_index >= total_tokens:
                        raise RuntimeError(f"Document start index {start_index:,d} from metadata file for source '{data_path}' with {total_tokens:,d} tokens is out-of-bounds")
                    if end_index > total_tokens:
                        raise RuntimeError(f"Document end index {end_index:,d} from metadata file for source '{data_path}' with {total_tokens:,d} tokens is out-of-bounds")
                yield (start_index, end_index)

def iter_document_indices_with_max_sequence_length(data_path: PathOrStr, max_sequence_length: int, *, local_cache: Optional[PathOrStr]=None, use_array_if_local: Optional[bool]=None, eos_token_id: Optional[int]=None, dtype=None, long_doc_strategy: LongDocStrategy=LongDocStrategy.truncate) -> Generator[Tuple[int, int], None, None]:
    for start_idx, end_idx in iter_document_indices(data_path, local_cache=local_cache, use_array_if_local=use_array_if_local, eos_token_id=eos_token_id, dtype=dtype):
        if end_idx - start_idx > max_sequence_length:
            if long_doc_strategy == LongDocStrategy.truncate:
                yield (start_idx, start_idx + max_sequence_length)
            elif long_doc_strategy == LongDocStrategy.fragment:
                for new_start_idx in range(start_idx, end_idx, max_sequence_length):
                    yield (new_start_idx, min(end_idx, new_start_idx + max_sequence_length))
            else:
                raise NotImplementedError(long_doc_strategy)
        else:
            yield (start_idx, end_idx)

def get_document_indices(data_path: PathOrStr, local_cache: Optional[PathOrStr]=None) -> List[Tuple[int, int]]:
    return list(iter_document_indices(data_path, local_cache=local_cache))

def load_array_slice(path: PathOrStr, start_idx: int, end_idx: int, dtype: Union[Type[np.uint8], Type[np.uint16], Type[np.uint32], Type[np.uint64], Type[np.bool_]]) -> np.ndarray:
    item_size = dtype(0).itemsize
    bytes_start = start_idx * item_size
    num_bytes = (end_idx - start_idx) * item_size
    buffer = get_bytes_range(path, bytes_start, num_bytes)
    return np.frombuffer(buffer, dtype=dtype)

def load_array_slice_into_tensor(path: PathOrStr, start_idx: int, end_idx: int, dtype: Union[Type[np.uint8], Type[np.uint16], Type[np.uint32], Type[np.uint64], Type[np.bool_]]) -> torch.Tensor:
    array = load_array_slice(path, start_idx, end_idx, dtype)
    if dtype == np.bool_:
        return torch.tensor(array)
    else:
        return torch.tensor(array.astype(np.int_), dtype=torch.long)

def get_document_lengths(input_ids: torch.Tensor, eos_token_id: int, bos_token_id: Optional[int]=None) -> torch.Tensor:
    if bos_token_id is None:
        doc_boundaries = torch.cat([torch.tensor([-1], dtype=torch.int32), (input_ids == eos_token_id).nonzero(as_tuple=True)[0].to(dtype=torch.int32), torch.tensor([] if input_ids[-1] == eos_token_id else [input_ids.shape[0] - 1], dtype=torch.int32)])
    else:
        doc_boundaries = torch.cat([torch.tensor([-1], dtype=torch.int32), torch.logical_and(input_ids[:-1] == eos_token_id, input_ids[1:] == bos_token_id).nonzero(as_tuple=True)[0].to(dtype=torch.int32), torch.tensor([input_ids.shape[0] - 1], dtype=torch.int32)])
    return doc_boundaries[1:] - doc_boundaries[:-1]

def get_cumulative_document_lengths(doc_lens: torch.Tensor) -> torch.Tensor:
    return torch.cat([torch.tensor([0], dtype=torch.int32, device=doc_lens.device), torch.cumsum(doc_lens.masked_select(doc_lens != 0), 0, dtype=torch.int32)])

def iter_batched(iterable: Iterable[Dict[str, Any]], batch_num_tokens: int) -> Iterable[Tuple[Dict[str, Any], ...]]:
    batch: List[Dict[str, Any]] = []
    tokens = 0
    shape: Optional[Tuple[int, ...]] = None
    for x in iterable:
        x_num_tokens = x['input_ids'].numel()
        assert x_num_tokens <= batch_num_tokens, f'{x_num_tokens} > {batch_num_tokens}'
        if tokens + x_num_tokens > batch_num_tokens:
            yield tuple(batch)
            batch.clear()
            tokens = 0
            shape = None
        batch.append(x)
        tokens += x_num_tokens
        if shape is not None and shape != x['input_ids'].shape:
            raise RuntimeError(f"Items in batch don't have the same shape! Expected {shape}, got {tuple(x['input_ids'].shape)}")
        shape = tuple(x['input_ids'].shape)
    if batch:
        yield tuple(batch)

@contextmanager
def memmap_to_write(path: Path, *, shape: Tuple[int, ...], dtype: Union[Type[np.uint8], Type[np.uint16], Type[np.uint32], Type[np.uint64], Type[np.bool_]]) -> Generator[np.ndarray, None, None]:
    path.parent.mkdir(exist_ok=True, parents=True)
    tmp_path = path.with_suffix(f'.{random.randint(0, 2 ** 32)}.npy.tmp')
    mmap = np.memmap(tmp_path, dtype=dtype, mode='w+', shape=shape)
    try:
        yield mmap
    except BaseException:
        tmp_path.unlink(missing_ok=True)
    mmap.flush()
    del mmap
    tmp_path.replace(path)

def write_array_to_disk(arr: np.ndarray, path: Path):
    with memmap_to_write(path, dtype=arr.dtype, shape=arr.shape) as mmap:
        mmap[:] = arr

def divide_into_buckets(n: int, b: int) -> List[int]:
    buckets: List[int] = []
    while (buckets_remaining := (b - len(buckets))) > 0:
        c = math.ceil(n / buckets_remaining)
        n -= c
        buckets.append(c)
    return buckets

def chunk_array(arr: np.ndarray, chunk_sizes: Sequence[int]) -> List[np.ndarray]:
    assert len(arr.shape) == 1
    assert sum(chunk_sizes) == arr.shape[0]
    offset = 0
    chunks = []
    for n in chunk_sizes:
        chunks.append(arr[offset:offset + n])
        offset += n
    return chunks

def get_rng(seed: int) -> np.random.Generator:
    return np.random.Generator(np.random.PCG64(seed=seed))

def bucket_documents(path: PathOrStr, target: Path, *, buckets: Sequence[int], eos_token_id: int, dtype: Union[Type[np.uint8], Type[np.uint16], Type[np.uint32], Type[np.uint64]], indices_dtype: Union[Type[np.uint8], Type[np.uint16], Type[np.uint32], Type[np.uint64]]=np.uint32) -> Tuple[int, int]:
    max_sequence_length = max(buckets)
    min_sequence_length = min(buckets)
    total_og_docs = 0
    indices = []
    for start_idx, end_idx in iter_document_indices(path, eos_token_id=eos_token_id, dtype=dtype):
        total_og_docs += 1
        bin_decomp = capped_powers_of_2(end_idx - start_idx, max_sequence_length)
        for x in bin_decomp:
            if x < min_sequence_length:
                break
            indices.append(start_idx)
            indices.append(start_idx + x)
            start_idx += x
    if not indices:
        raise RuntimeError(f"Failed to produce any bucketed documents for source file at '{path}'")
    with memmap_to_write(target, dtype=indices_dtype, shape=(len(indices),)) as indices_mmap:
        indices_mmap[:] = indices
    return (total_og_docs, len(indices) // 2)

def segment_documents_into_instances(path: PathOrStr, target: Path, *, max_sequence_length: int, eos_token_id: int, dtype: Union[Type[np.uint8], Type[np.uint16], Type[np.uint32], Type[np.uint64]], indices_dtype: Union[Type[np.uint8], Type[np.uint16], Type[np.uint32], Type[np.uint64]]=np.uint32, sample: Optional[Tuple[int, int]]=None) -> Tuple[int, int]:
    total_og_docs = 0
    idx_gen = (idx for start_idx, end_idx in iter_document_indices(path, eos_token_id=eos_token_id, dtype=dtype) for idx in (start_idx, start_idx + min(end_idx - start_idx, max_sequence_length)))
    indices = np.fromiter(idx_gen, dtype=indices_dtype)
    total_og_docs = len(indices) // 2
    if sample is not None:
        max_instances, seed = sample
        rng = get_rng(seed)
        indices = rng.choice(indices.reshape(-1, 2), size=max_instances).reshape(-1)
    if indices.size == 0:
        raise RuntimeError(f"Failed to produce any documents from '{path}'")
    with memmap_to_write(target, dtype=indices_dtype, shape=(indices.size,)) as indices_mmap:
        indices_mmap[:] = indices
    return (total_og_docs, len(indices) // 2)

